body.query:
  query Project($key: String!) {
    resource(id: $key) {
      ...ResourceRedirectDetails
      ... on GbifProject {
        ...ProjectPage
      }
    }
    # The Project Datasets tab also uses some data from this loader and defines its own data needs in this fragment
    ...ProjectDatasetsTab
  }

fragment ResourceRedirectDetails on Resource {
  __typename
  ... on Article {
    id
    title
    urlAlias
  }
  ... on Composition {
    id
    maybeTitle: title
    urlAlias
  }
  ... on DataUse {
    id
    title
  }
  ... on Document {
    id
    title
  }
  ... on MeetingEvent {
    id
    title
  }
  ... on News {
    id
    title
  }
  ... on Programme {
    id
    title
  }
  ... on GbifProject {
    id
    title
  }
  ... on Tool {
    id
    title
  }
}

fragment ProjectPage on GbifProject {
  # Define the values used by this page
  title
  excerpt
  status
  start
  end
  fundsAllocated
  primaryLink {
    label
    url
  }
  ...ProjectFundingBanner
  # The Project About tab uses the data from this loader and defines its own data needs in this fragment
  ...ProjectAboutTab
}

fragment ProjectFundingBanner on GbifProject {
  __typename
  fundsAllocated
  programme {
    ...ProgrammeFundingBanner
  }
  overrideProgrammeFunding {
    ...FundingOrganisationDetails
  }
}

fragment ProgrammeFundingBanner on Programme {
  __typename
  fundingOrganisations {
    ...FundingOrganisationDetails
  }
}

fragment FundingOrganisationDetails on FundingOrganisation {
  id
  title
  url
  logo {
    title
    file {
      url
    }
  }
}

fragment ProjectAboutTab on GbifProject {
  projectId
  id
  body
  start
  end
  status
  fundsAllocated
  matchingFunds
  grantType
  purposes
  leadPartner {
    ...ParticipantOrFundingOrganisationDetails
  }
  additionalPartners {
    ...ParticipantOrFundingOrganisationDetails
  }
  leadContact
  fundingOrganisations {
    ...ParticipantOrFundingOrganisationDetails
  }
  programme {
    fundingOrganisations {
      ...ParticipantOrFundingOrganisationDetails
    }
  }
  overrideProgrammeFunding {
    ...ParticipantOrFundingOrganisationDetails
  }
  programme {
    id
    title
  }
  primaryImage {
    ...ArticleBanner
  }
  primaryLink {
    label
    url
  }
  secondaryLinks {
    label
    url
  }
  documents {
    ...DocumentPreview
  }
}

fragment ParticipantOrFundingOrganisationDetails on ParticipantOrFundingOrganisation {
  __typename
  ... on FundingOrganisation {
    id
    title
    url
  }
  ... on Participant {
    id
    title
    type
    countryCode
  }
}

fragment ArticleBanner on AssetImage {
  description
  title
  file {
    url
    details {
      image {
        width
        height
      }
    }
    normal: thumbor(width: 1200, height: 500)
    mobile: thumbor(width: 800, height: 400)
  }
}

fragment DocumentPreview on DocumentAsset {
  title
  file {
    url
    fileName
    contentType
    volatile_documentType
    details {
      size
    }
  }
}

fragment ProjectDatasetsTab on Query {
  gbifProject(id: $key) {
    projectId
  }
  datasetsHelp: help(identifier: "how-to-link-datasets-to-my-project-page") {
    title
  }
}
